/* ---------- map ---------- */
// zoomSnap 0.25 lets the default view fit the screen width exactly (whole zoom levels are too small on narrow screens); the buttons step half a level
// Wheel / trackpad zoom uses the smooth zoom below (Leaflet's scrollWheelZoom is off); the wheel* options only matter if it falls back to the default
// Latitude is limited to 60°S–80°N (dropping the empty polar areas); longitude spans three worlds so the map can be dragged sideways indefinitely
const LAT_BAND = L.latLngBounds([-60,-540],[80,540]);
// On portrait phones the map is a world-proportioned strip: width : height = one full circle of longitude : this latitude band (Mercator); CSS reads it from --map-aspect
const mercY = lat => Math.log(Math.tan(Math.PI/4 + lat*Math.PI/360));
document.documentElement.style.setProperty("--map-aspect", (2*Math.PI / (mercY(LAT_BAND.getNorth()) - mercY(LAT_BAND.getSouth()))).toFixed(4));
const map = L.map("map",{worldCopyJump:true, zoomControl:true, zoomSnap:0.25, zoomDelta:0.5,
  wheelPxPerZoomLevel:110, wheelDebounceTime:15, scrollWheelZoom:false,
  maxBounds:LAT_BAND, maxBoundsViscosity:1}).setView([25,160],2);
// Turn zoomSnap off temporarily to set an exact view: setView / getBoundsZoom normally snap to multiples of 0.25, which on phones crops the world or leaves gaps
function exactly(fn){
  const snap = map.options.zoomSnap;
  map.options.zoomSnap = 0;
  try{ return fn(); } finally { map.options.zoomSnap = snap; }
}
// Minimum zoom follows the container size: any further out and the world no longer fills the height (gaps on portrait phones). Recomputed on resize and rotation
function fitMinZoom(){
  const size = map.getSize();
  if(!size.x || !size.y) return;                       // skip while the map is hidden (on the photos page etc.)
  // The floor is the exact zoom at which the world fills the height. getBoundsZoom never returns less than the current minimum, so release it first; otherwise the floor can't drop when the screen shrinks (rotation, smaller window)
  map.options.minZoom = 0;
  const z = exactly(() => map.getBoundsZoom(LAT_BAND, true));
  map.options.minZoom = z;
  // Not setMinZoom: below the new floor it starts a zoom animation, and any setView before it finishes is swallowed (that is how the default view used to get lost on load)
  if(map.getZoom() < z) exactly(() => map.setZoom(z, {animate:false}));
}
fitMinZoom();
map.on("resize", fitMinZoom);
// Zoomed far out (the whole world on screen): add .far to the map for smaller pins (see style.css)
const updateFar = () => map.getContainer().classList.toggle("far", map.getZoom() < 1.6);
map.on("zoom", updateFar);
updateFar();
let worldViewShown = false;                              // is the map still at the default view (untouched, no continent picked)? If so, re-fit it when the screen size changes

/* Smooth wheel zoom: Mac trackpad pinch (a wheel event with ctrlKey), two-finger scroll and mouse wheel all zoom continuously around the pointer.
   Same approach as the SmoothWheelZoom plugin: the scroll amount becomes a target zoom, each frame moves part of the way there with map._move
   (no zoomSnap rounding), and a final moveend loads the tiles. Pinch zoom on phones uses Leaflet's own touchZoom and is unaffected. */
L.Map.SmoothWheelZoom = L.Handler.extend({
  addHooks(){ L.DomEvent.on(this._map.getContainer(), "wheel", this._onWheel, this); },
  removeHooks(){ L.DomEvent.off(this._map.getContainer(), "wheel", this._onWheel, this); },
  _onWheel(e){
    const map = this._map;
    L.DomEvent.preventDefault(e);
    const unit = e.deltaMode===1 ? 16 : e.deltaMode===2 ? 400 : 1;        // lines / pages → pixels
    const perLevel = e.ctrlKey ? 45 : 110;                                // pinch deltas are small, so more sensitive; one wheel notch ≈ 100px ≈ 0.9 levels
    if(!this._wheeling){
      this._wheeling = true;
      map._stop(); if(map._panAnim) map._panAnim.stop();
      this._zoom = this._goal = map.getZoom();
      map._moveStart(true, false);
    }
    this._goal = Math.max(map.getMinZoom(), Math.min(map.getMaxZoom(), this._goal - e.deltaY*unit/perLevel));
    const mouse = map.mouseEventToContainerPoint(e);
    if(!this._mouse || !mouse.equals(this._mouse) || !this._anchor){     // re-anchor only when the pointer moves, so errors don't accumulate frame by frame
      this._mouse = mouse;
      this._anchor = map.containerPointToLatLng(mouse);
    }
    clearTimeout(this._endTimer);
    if(!this._raf) this._raf = L.Util.requestAnimFrame(this._frame, this);
  },
  _frame(){
    const map = this._map;
    this._raf = null;
    const diff = this._goal - this._zoom;
    this._zoom = Math.abs(diff) < 0.003 ? this._goal : this._zoom + diff*0.3;    // ease: cover 30% of the remaining distance each frame
    map._move(map._limitCenter(this._centerFor(this._zoom), this._zoom, map.options.maxBounds), this._zoom);   // stay inside the latitude band even when zooming out at the edge
    if(this._zoom !== this._goal) this._raf = L.Util.requestAnimFrame(this._frame, this);
    else this._endTimer = setTimeout(()=>{ this._wheeling = false; this._anchor = null; map._moveEnd(true); }, 120);
  },
  _centerFor(zoom){
    // anchor on the pointer: the point under it when zooming started stays under it at the new zoom
    const map = this._map, viewHalf = map.getSize()._divideBy(2);
    return map.unproject(map.project(this._anchor, zoom).subtract(this._mouse.subtract(viewHalf)), zoom);
  },
});
