const pinSvg = (w,h) => `<svg class="pin-svg" viewBox="0 0 16 22" width="${w}" height="${h}" aria-hidden="true">
  <path fill-rule="evenodd" d="M8 21.5S1 13.6 1 8a7 7 0 0 1 14 0c0 5.6-7 13.5-7 13.5ZM8 5a3 3 0 1 0 0 6a3 3 0 1 0 0-6Z"/></svg>`;
