// above visited countries (350), below city markers (600)
map.createPane("flights").style.zIndex=380;
const flightColor = getComputedStyle(document.documentElement).getPropertyValue("--flight").trim();
const FLIGHT = {pane:"flights", color:flightColor, weight:1.5, opacity:.75, lineCap:"round", interactive:false};
const FLIGHT_HOVER = {weight:3, opacity:.95};
const flightLayer = L.layerGroup();
// Flights crossing 180° are split into two parts in the data; copies at ±360° join them up when the map is centred on the Pacific
// A flight's bounds and midpoint: parts crossing 180° are first joined into continuous longitudes (e.g. 140° becomes -220°) so the view centres on the Pacific
function flightExtent(f){
  const parts = f.geometry.type==="LineString" ? [f.geometry.coordinates] : f.geometry.coordinates;
  let shift = 0; const pts = [];
  parts.forEach((l,i)=>{
    if(i){ const [px] = parts[i-1][parts[i-1].length-1], [cx] = l[0];
      if(Math.abs(px)===180 && px===-cx) shift += px>0 ? 360 : -360; }
    l.forEach(([x,y])=>pts.push([y, x+shift]));
  });
  return {bounds: L.latLngBounds(pts), mid: L.latLng(pts[Math.floor(pts.length/2)])};
}
const worldCopies = f => {
  const lines = f.geometry.type==="LineString" ? [f.geometry.coordinates] : f.geometry.coordinates;
  return {...f, geometry:{type:"MultiLineString", coordinates:
    [-360,0,360].flatMap(d=>lines.map(l=>l.map(([x,y])=>[x+d,y])))}};
};
map.createPane("flightLabels").style.zIndex=590;
