/* ---------- photos page (#photos): every place's photos, shuffled each time, in a masonry layout ---------- */
let shuffled = [];
function shuffle(a){ for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
function showPhotos(){
  shuffled = shuffle(CITIES.flatMap(c=>c.photos.map(f=>({c,f}))));
  const cities = new Set(shuffled.map(x=>x.c.id)).size;
  showPage(`<div class="page-in">
    <header class="page-head">
      <div><h2>Photos</h2><p class="sub">${plural(shuffled.length,"photo")} · ${plural(cities,"place")}</p></div>
      <button class="btn" data-act="shuffle">↻ Shuffle</button>
    </header>
    <div class="masonry">${shuffled.map(({c,f},k)=>`
      <figure tabindex="0" data-k="${k}"><img src="${src(c,f)}" alt="${c.en}${filmOf(c,f)?" (film)":""}" loading="lazy" decoding="async" onerror="this.closest('figure').remove()">
        <figcaption>${c.en}</figcaption>${filmOf(c,f)?FILM_TAG:""}</figure>`).join("")}
    </div></div>`, "Photos", "photos");
}

/* ---------- film page (#film; #film.<roll> jumps to that roll): one horizontal strip per roll, filterable by film stock / camera ---------- */
// All film photos grouped by roll. Rolls with a start date come first, oldest first, then the rest by name; frames in roll order (frameCmp)
function filmRolls(){
  const by = new Map();
  CITIES.forEach(c => c.photos.forEach(f => { const fi = filmOf(c,f); if(!fi) return;
    if(!by.has(fi.roll)) by.set(fi.roll, []);
    by.get(fi.roll).push({c,f}); }));
  return [...by].map(([roll, photos]) => ({roll, info:rollInfo(roll), photos:photos.sort(frameCmp)}))
    .sort((a,b) => (a.info.date_from||"9999").localeCompare(b.info.date_from||"9999") || natCmp(a.roll,b.roll));
}
const fmtRange = (a,b) => !a && !b ? "" : (!b || a===b) ? fmtDate(a||b) : !a ? fmtDate(b) : `${fmtDate(a)} – ${fmtDate(b, a.slice(0,4)!==b.slice(0,4))}`;
let filmFilter = {film_stock:"", camera:""};            // current filter: film stock, camera (empty = all)
/* Box images: box_image in rolls.csv (a PNG path such as assets/film/boxes/ektar100.png); one roll per stock is enough for all its rolls.
   A .webp with the same name is preferred, falling back to the PNG; if that fails too, the cabinet shows a text card and the box beside the title is dropped */
const FILM_MAKERS = /^(kodak|fujifilm|fuji|ilford|kentmere|cinestill|lomography|agfaphoto|agfa|foma|rollei|harman|adox|orwo)\s+/i;
const stockShort = stock => String(stock || "").replace(FILM_MAKERS, "");          // "Kodak Ektar 100" → "Ektar 100"
const boxOf = stock => Object.values(ROLLS).find(r => r.film_stock === stock && r.box_image)?.box_image || "";
const boxCard = (name, iso) => `<span class="box-card"><b>${esc(name)}</b>${iso ? `<small>ISO ${esc(iso)}</small>` : ""}</span>`;
const boxImg = (src, alt) => /\.png$/i.test(src)
  ? `<picture><source type="image/webp" srcset="${esc(src.replace(/\.png$/i, ".webp"))}"><img src="${esc(src)}" alt="${esc(alt)}" draggable="false" onerror="boxImgError(this)"></picture>`
  : `<img src="${esc(src)}" alt="${esc(alt)}" draggable="false" onerror="boxImgError(this)">`;
function boxImgError(img){
  const source = img.parentElement?.querySelector("source");
  if(source){ source.remove(); return; }                 // WebP failed: remove it and the browser falls back to the PNG
  const rb = img.closest(".roll-box"); if(rb){ rb.remove(); return; }
  const art = img.closest(".box-art"); if(art) art.innerHTML = boxCard(art.dataset.name, art.dataset.iso);
}
function filmGroupHtml({roll, info, photos}){
  const cities = [...new Map(photos.map(({c}) => [c.id, c])).values()];
  const meta = [info.camera, info.format, info.iso && `ISO ${info.iso}`, fmtRange(info.date_from, info.date_to)].filter(Boolean).map(esc).join(" · ");
  return `<section class="roll" id="roll-${esc(roll)}" data-roll="${esc(roll)}">
    <header class="roll-head">
      <div class="roll-id">${esc(roll||"No roll")}<span>${plural(photos.length,"frame")}</span></div>
      <div class="roll-title"><h3>${esc(info.film_stock || "Film")}</h3>${boxOf(info.film_stock) ? `<button type="button" class="roll-box" data-stock="${esc(info.film_stock)}" aria-pressed="${filmFilter.film_stock===info.film_stock}" title="Show only ${esc(info.film_stock)}">${boxImg(boxOf(info.film_stock), info.film_stock)}</button>` : ""}</div>
      ${meta?`<p class="roll-meta">${meta}</p>`:""}
      <p class="roll-cities">${cities.map(c => `<a href="#${c.id}">${flag(c)}${esc(c.en)}</a>`).join("")}</p>
    </header>
    ${stripHtml(photos, roll, photos.map((_,k) => k+1), true)}
  </section>`;
}
function showFilm(focusRoll){
  if(focusRoll) filmFilter = {film_stock:"", camera:""};   // coming from the lightbox's "View this roll": clear the filter so the roll isn't hidden
  showPage(`<div class="page-in film-page">
    <header class="page-head"><div><h2>Film</h2><p class="sub" id="filmSub"></p></div></header>
    <div id="filmCabinet"></div><div id="filmFilters"></div><div id="filmRolls"></div></div>`, "Film", "film");
  rollsData.then(() => {
    if(!document.getElementById("filmRolls")) return;      // already left the film page
    const rolls = filmRolls();
    const opts = key => [...new Set(rolls.map(r => r.info[key]).filter(Boolean))].sort(natCmp);
    const draw = () => {
      const shown = rolls.filter(r => (!filmFilter.film_stock || r.info.film_stock===filmFilter.film_stock) && (!filmFilter.camera || r.info.camera===filmFilter.camera));
      const n = shown.reduce((a,r)=>a+r.photos.length, 0);
      document.getElementById("filmSub").textContent = rolls.length ? `${plural(n,"photo")} · ${plural(shown.length,"roll")}` : "";
      STRIPS = [];
      document.getElementById("filmRolls").innerHTML = shown.length ? shown.map(filmGroupHtml).join("") : `<p class="empty">${rolls.length?"No rolls match.":"No film photos yet."}</p>`;
      initStrips();
    };
    // filter bar: hidden for film stock or camera when there is only one option
    const bar = [["film_stock","film stock"],["camera","camera"]].map(([key,label]) => ({key, label, list:opts(key)})).filter(x => x.list.length > 1);
    const drawBar = () => {
      document.getElementById("filmFilters").innerHTML = bar.map(({key,label,list}) =>
        `<nav class="chips tchips" aria-label="Filter by ${label}">${[["",`All ${label}s`], ...list.map(v=>[v,v])].map(([v,n]) =>
          `<button type="button" class="chip" data-key="${key}" data-val="${esc(v)}"${filmFilter[key]===v?' aria-current="true"':""}>${esc(n)}</button>`).join("")}</nav>`).join("");
    };
    // Film cabinet: one box per stock used (same order as the film stock chips); click to show only that stock, click again to clear; kept in sync with the chips
    const cab = document.getElementById("filmCabinet");
    const stocks = opts("film_stock").map(stock => { const rs = rolls.filter(r => r.info.film_stock === stock);
      return {stock, rolls:rs.length, photos:rs.reduce((a,r)=>a+r.photos.length, 0), iso:rs.map(r=>r.info.iso).find(Boolean) || ""}; });
    cab.innerHTML = stocks.length ? `<div class="cabinet" role="group" aria-label="Film cabinet: filter by stock"><div class="cab-row">${stocks.map(x => `
      <button type="button" class="cab-box" data-stock="${esc(x.stock)}" aria-pressed="false" title="Show only ${esc(x.stock)}">
        <span class="box-art" data-name="${esc(stockShort(x.stock))}" data-iso="${esc(x.iso)}">${boxOf(x.stock) ? boxImg(boxOf(x.stock), x.stock) : boxCard(stockShort(x.stock), x.iso)}</span>
        <span class="cab-name">${esc(stockShort(x.stock))}</span><span class="cab-count">${plural(x.rolls,"roll")} · ${plural(x.photos,"photo")}</span>
      </button>`).join("")}</div></div>` : "";
    const syncCabinet = () => {
      cab.querySelector(".cabinet")?.classList.toggle("picked", !!filmFilter.film_stock);
      cab.querySelectorAll(".cab-box").forEach(b => b.setAttribute("aria-pressed", b.dataset.stock === filmFilter.film_stock));
    };
    // pick a stock (shared by the cabinet and the boxes beside titles): when clicked beside a title, keep that roll where it was on screen after redrawing
    const pickStock = (stock, anchor) => {
      const id = anchor?.id, top = anchor?.getBoundingClientRect().top;
      filmFilter.film_stock = filmFilter.film_stock === stock ? "" : stock;
      drawBar(); draw(); syncCabinet();
      const now = id && document.getElementById(id); if(now) scrollBy(0, now.getBoundingClientRect().top - top);
    };
    drawBar(); draw(); syncCabinet();
    cab.onclick = e => { const b = e.target.closest(".cab-box"); if(b) pickStock(b.dataset.stock); };
    document.getElementById("filmRolls").onclick = e => { const b = e.target.closest(".roll-box"); if(b) pickStock(b.dataset.stock, b.closest(".roll")); };
    document.getElementById("filmFilters").onclick = e => {
      const b = e.target.closest(".chip"); if(!b) return;
      filmFilter[b.dataset.key] = b.dataset.val; drawBar(); draw(); syncCabinet();
    };
    if(focusRoll) document.getElementById("roll-"+focusRoll)?.scrollIntoView({block:"start"});
  });
}

/* ---------- articles page (#articles): every place's articles, newest first, undated ones last ---------- */
const firstSentence = s => (String(s||"").match(/^.*?(?:[!?]|\.(?=\s|$)|$)/) || [""])[0];
function showArticles(){
  const list = CITIES.flatMap(c=>(c.articles||[]).map((a,k)=>({c,a,k})))
    .sort((x,y)=>(y.a.date||"").localeCompare(x.a.date||""));
  showPage(`<div class="page-in">
    <header class="page-head"><div><h2>Articles</h2><p class="sub">${plural(list.length,"article")}</p></div></header>
    ${list.length?`<ol class="alist">${list.map(({c,a,k})=>`
      <li><a href="${articleHref(c,a)}">
        <span>
          <span class="ad">${a.date?fmtDate(a.date):"Undated"}</span>
          <b>${esc(a.title)}</b>
          <span class="acity">${flag(c)}${c.en}</span>
          <small>${firstSentence(preview(a))}</small>
        </span>
        ${a.cover?`<span class="ac" style="background-image:url('${src(c,a.cover)}')"></span>`:"<span></span>"}
      </a></li>`).join("")}</ol>`:`<p class="empty">No articles yet.</p>`}
  </div>`, "Articles", "articles");
}

/* ---------- transport page (#transport, filters such as #transport.rail): flights + rail / drive / water, by departure time, grouped by year ---------- */
const km = (a,b)=>{   // great-circle distance; a and b are [lng, lat]
  const r=Math.PI/180, [x1,y1]=a, [x2,y2]=b;
  const h=Math.sin((y2-y1)*r/2)**2 + Math.cos(y1*r)*Math.cos(y2*r)*Math.sin((x2-x1)*r/2)**2;
  return 2*6371*Math.asin(Math.sqrt(h));
};
const TRANSPORT_FILTERS = [["","All"],["air","Air"],["rail","Rail"],["drive","Drive"],["water","Water"]];
function showTransport(filter){
  if(!TRANSPORT_FILTERS.some(([k])=>k===filter)) filter = "";
  showPage(`<div class="page-in">
    <header class="page-head"><div><h2>Transport</h2></div></header>
    <nav class="chips tchips" aria-label="Filter by mode">${TRANSPORT_FILTERS.map(([k,n])=>
      `<a href="#transport${k?"."+k:""}"${k===filter?' aria-current="true"':""}>${k?modeIcon(k,"micon sm"):""}${n}</a>`).join("")}</nav>
    <div id="transportList"><p class="empty">Loading…</p></div></div>`, "Transport", "transport");
  Promise.allSettled([flightsData, routesData]).then(([fl, rt])=>{
    const box = document.getElementById("transportList"); if(!box) return;   // already left the transport page
    const items = [];
    if(fl.status==="fulfilled") fl.value.features.forEach(f=>{
      const p=f.properties, parts=f.geometry.type==="LineString"?[f.geometry.coordinates]:f.geometry.coordinates;
      const a=p.from_pos||parts[0][0], b=p.to_pos||parts.at(-1).at(-1);
      items.push({mode:"air", id:p.id, logo:logoHtml(p), from:p.from_iata||"?", to:p.to_iata||"?", sub:(p.from_city||p.to_city)?`${p.from_city||"?"} → ${p.to_city||"?"}`:"",
        date:p.date, sort:p.dep_utc||p.date||"", number:p.flight_no, extra:p.aircraft, dist:km(a,b), minutes:p.minutes, times:timeLine(p)});
    });
    if(rt.status==="fulfilled") rt.value.features.forEach(f=>{
      const p=f.properties;
      const r = p.mode==="rail" && p.rail;
      const chain = !r && p.stops?.length>2;
      items.push({mode:MODES[p.mode]?p.mode:"drive", id:p.id, logo:r?opLogo(r):"", from:chain?p.stops.join(" → "):p.from||"?", to:chain?"":p.to||"?",
        sub: r ? [(r.dep_station||r.arr_station)?`${r.dep_station||"?"} → ${r.arr_station||"?"}`:"", r.operator_name].filter(Boolean).join(" · ") : (p.operator||""),
        date:p.date, sort:(r&&r.dep_local)||p.date||"", number:r?[r.train_number,r.train_name].filter(Boolean).join(" · "):p.number,
        extra:r?[r.rolling_stock,r.class,railBerth(r)].filter(Boolean).join(" · ")||(p.stops?.length>2?plural(p.stops.length-2,"stop"):""):"",
        dist:+p.distance_km||0, minutes:p.minutes, times:r?railTimes(r):""});
    });
    // by departure time; ties (e.g. only a date) keep their original order (Array sort is stable)
    const list = items.filter(x=>!filter || x.mode===filter).sort((x,y)=>(x.sort||"9999").localeCompare(y.sort||"9999"));
    const total = list.reduce((s,x)=>s+(x.minutes||0),0), dist = list.reduce((s,x)=>s+(x.dist||0),0);
    const year = x => (x.date||"").slice(0,4) || "Undated";
    const years = [...new Set(list.map(year))];
    box.innerHTML = !list.length ? `<p class="empty">Nothing here yet.</p>` : `
      <div class="fsum"><div><b>${list.length}</b>${list.length===1?"trip":"trips"}</div><div><b>${Math.round(dist).toLocaleString("en-US")}</b>km</div><div><b>${total?fmtMinutes(total):"—"}</b>travel time</div></div>
      ${years.map(y=>`<h3 class="fyear">${y}</h3><ol class="flist">${list.filter(x=>year(x)===y).map(x=>`
        <li><button class="frow trow" data-mode="${x.mode}" data-id="${esc(x.id)}">
          <span class="tr-icon${x.logo?" has-logo":""}">${x.logo||modeIcon(x.mode,"micon big")}</span>
          <span><span class="fr-route${x.to?"":" chain"}">${esc(x.from)}${x.to?` → ${esc(x.to)}`:""}</span>${x.sub?`<span class="fr-city"><br>${esc(x.sub)}</span>`:""}</span>
          <span class="fr-meta">${[fmtDate(x.date),x.number].filter(Boolean).map(esc).join(" · ")||"Date TBC"}${x.times?`<br>${esc(x.times)}`:""}<br>${[x.extra,kmText(x.dist),fmtMinutes(x.minutes)].filter(Boolean).map(esc).join(" · ")}</span>
        </button></li>`).join("")}</ol>`).join("")}`;
  });
}

/* ---------- routing ---------- */
function route(){
  const h = decodeURIComponent(location.hash.slice(1));
  lb.hidden = true;
  if(devlog?.open) devlog.close();                              // back button or a link while the changelog is open
  if(h==="photos") return showPhotos();
  if(h==="film" || h.startsWith("film.")) return showFilm(h.slice(5));
  if(h==="articles") return showArticles();
  if(h==="flights"){ location.replace("#transport"); return; }       // old link
  if(h==="transport" || h.startsWith("transport.")) return showTransport(h.split(".")[1]||"");
  const reg = REGION_LIST.find(r=>r.slug===h);
  const [id,art] = h.split(".");
  const c = CITIES.find(x=>x.id===id);
  // articles: #<city-id>.2025-11-03 (a second one that day is 2025-11-03-2); the old #<city-id>.a1 = first article by date
  const k = !c || !art ? -1 : /^a\d+$/.test(art) ? parseInt(art.slice(1),10)-1 : c.articles.findIndex(a=>a.slug===art);
  if(!reg && c && c.articles[k]) return showArticle(c,k);
  if(!reg && c) return showCity(c);
  // anything else (# or unrecognised) goes to the map
  // map (# is everything, #europe etc. a continent view). Returning from a city page with the same continent keeps the current view
  if(mapView.hidden || !rphotoShown) randomPhoto();          // a new photo each time the map is re-entered from another page, but not when switching continents
  current=null; page.hidden=true; page.innerHTML=""; mapView.hidden=false; scrollTo(0,0);
  const slug = reg ? reg.slug : "";
  lastMapHash = slug;
  document.title = reg ? `${reg.name} · ${SITE}` : SITE; setNav("map");
  const changed = slug !== (region?.slug||"");
  setTimeout(()=>{
    map.invalidateSize();
    if(pendingFocus){ setRegion(slug,{fit:false}); focusTransport(...pendingFocus); pendingFocus=null; }
    else setRegion(slug,{fit:changed||firstRoute, animate:!firstRoute});
    firstRoute = false;
  },0);
}
addEventListener("hashchange",route);
page.addEventListener("click",e=>{
  if(e.target.closest("[data-act=map]")) location.hash=lastMapHash;
  if(e.target.closest("[data-act=shuffle]")) showPhotos();
  const g=e.target.closest("[data-go]"); if(g) location.hash=g.dataset.go;
  const s=e.target.closest(".shot"); if(s) openLb(cityDigital, +s.dataset.k, false);   // includes the small places' photos
  const sb=e.target.closest(".strip-btn"); if(sb){ stepStrip(sb.closest(".strip"), sb.classList.contains("next")?1:-1); return; }
  const sf=e.target.closest(".sframe"); if(sf){ if(!underCassette(sf, e)) openLb(STRIPS[+sf.closest(".strip").dataset.strip], +sf.dataset.k, true); return; }   // pages through this strip
  const fig=e.target.closest(".masonry figure"); if(fig) openLb(shuffled, +fig.dataset.k, true);
  const fr=e.target.closest(".trow"); if(fr){ pendingFocus=[fr.dataset.mode, fr.dataset.id]; location.hash=""; }
});
page.addEventListener("keydown",e=>{
  const fig=e.target.closest(".masonry figure, .sframe");
  if(fig && (e.key==="Enter"||e.key===" ")){ e.preventDefault(); fig.click(); }
});

/* ---------- lightbox: city order on city pages, shuffled order on the photos page, with a "Go to <place> →" link ---------- */
const lb=document.getElementById("lb"); let lbList=[], lk=0, lbLink=false;
function openLb(list,k,link){ lbList=list; lbLink=link; showLb(k); }
function showLb(k){
  lk=(k+lbList.length)%lbList.length; const {c,f}=lbList[lk];
  lb.innerHTML=`<div class="stage"><img src="${src(c,f)}" alt="${c.en}" onerror="this.outerHTML=window.__ph('${c.id}','${f}',${lk})">
    <div class="cap">${c.en} · ${f} · ${lk+1}/${lbList.length}${lbLink&&!filmOf(c,f)?`<a href="#${c.id}">Go to ${c.en} →</a>`:""}</div>
    ${filmOf(c,f)?`<div class="cap filmcap">${FILM_TAG}<span>${esc(filmLine(filmOf(c,f).roll))}</span><a href="#${c.id}">Go to ${c.en} →</a><a href="${filmHref(filmOf(c,f).roll)}">View this roll →</a></div>`:""}</div>
    <button class="x" aria-label="Close">×</button><button class="p" aria-label="Previous">‹</button><button class="n" aria-label="Next">›</button>`;
  lb.hidden=false;
}
lb.addEventListener("click",e=>{
  if(e.target.closest(".p")) showLb(lk-1); else if(e.target.closest(".n")) showLb(lk+1);
  else if(e.target.closest(".x")||e.target===lb) lb.hidden=true;
});
addEventListener("keydown",e=>{ if(lb.hidden) return;
  if(e.key==="Escape") lb.hidden=true; if(e.key==="ArrowLeft") showLb(lk-1); if(e.key==="ArrowRight") showLb(lk+1);});

/* ---------- sidebar: a random photo; click it to open its place ---------- */
// One photo picked at random from every place (a small place's photos count as its own); the card and name reserve their space first and the photo fades in once loaded; on error it tries another, and hides after three failures
const rphoto = document.getElementById("rphoto");
let rphotoShown = false, rphotoLast = "", rphotoTries = 0;
function randomPhoto(){
  if(!rphoto) return;                                       // don't break the page if a cached older index.html lacks this element
  const all = CITIES.flatMap(c=>c.photos.map(f=>({c,f})));
  if(!all.length){ rphoto.hidden = true; return; }
  let pick;
  do { pick = all[Math.floor(Math.random()*all.length)]; } while(all.length>1 && `${pick.c.id}/${pick.f}`===rphotoLast);
  const {c,f} = pick;
  rphotoLast = `${c.id}/${f}`; rphotoShown = true;
  rphoto.href = `#${c.id}`;
  rphoto.setAttribute("aria-label", `Random photo: ${c.en}. Open this place`);
  rphoto.innerHTML = `<img alt="" decoding="async" fetchpriority="low"><span class="rcap"><span class="rname">${flag(c)}${esc(c.en)}</span><span class="rgo" aria-hidden="true">→</span></span>`;
  const img = rphoto.querySelector("img");
  img.onload = () => { rphotoTries = 0; img.classList.add("on"); };
  img.onerror = () => { if(++rphotoTries < 3) randomPhoto(); else { rphoto.hidden = true; rphotoTries = 0; } };
  img.src = src(c,f);
  rphoto.hidden = false;
}

/* ---------- changelog: data/changelog.json, generated from the git history by tools/build_changelog.py ----------
   Opening the home page (map) pops up the full log (<dialog>, grouped by day, newest first); ×, Esc or a click outside closes it.
   The sidebar lists the latest UPDATES_SHOWN entries; clicking one or "View all" opens it again. Deep links (places, articles…) don't pop it up.
   When the log is empty, neither the sidebar block nor the dialog appears. Times are US Eastern (EDT / EST) */
const devlog = document.getElementById("devlog"), updates = document.getElementById("updates");
const UPDATES_SHOWN = 3;
const ET_FMT = new Intl.DateTimeFormat("en-US", {timeZone:"America/New_York", year:"numeric", month:"2-digit", day:"2-digit",
  weekday:"short", hour:"2-digit", minute:"2-digit", hourCycle:"h23", timeZoneName:"short"});
// UTC seconds → {day:"2026-10-14", wd:"Wed", hm:"11:11", tz:"EDT"} (Eastern Time)
function etTime(t){
  const p = Object.fromEntries(ET_FMT.formatToParts(new Date(t*1000)).map(x=>[x.type, x.value]));
  return {day:`${p.year}-${p.month}-${p.day}`, wd:p.weekday, hm:`${p.hour}:${p.minute}`, tz:p.timeZoneName};
}
const changelogData = fetch("data/changelog.json").then(r=>{ if(!r.ok) throw r.status; return r.json(); });
function devlogHtml(list){
  const days = [];
  list.forEach(e => { const et = etTime(e.t); if(days.at(-1)?.day !== et.day) days.push({...et, items:[]}); days.at(-1).items.push({...e, et}); });
  return days.map(d => `<section class="dl-day"><h3>${fmtDate(d.day)}<span>${d.wd}</span><span class="dl-n">${plural(d.items.length,"update")}</span></h3><ol>${
    d.items.map(e => `<li><time>${e.et.hm}<small>${e.et.tz}</small></time><div><p>${esc(e.msg)}</p>${
      e.tags.length ? `<div class="dl-tags">${e.tags.map(t=>`<span>${esc(t)}</span>`).join("")}</div>` : ""}</div></li>`).join("")
  }</ol></section>`).join("");
}
function openDevlog(){
  devlog.innerHTML = `<div class="dl-head"><div><h2 id="devlogTitle">Changelog</h2><p id="devlogSub">Times are US Eastern</p></div><button class="dl-x" type="button" aria-label="Close">×</button></div>
    <div class="dl-body"><p class="dl-empty">Loading…</p></div>`;
  devlog.showModal();
  changelogData.then(list => {
    document.getElementById("devlogSub").textContent = `Times are US Eastern · ${plural(list.length,"update")}`;
    devlog.querySelector(".dl-body").innerHTML = devlogHtml(list) || `<p class="dl-empty">No entries yet</p>`;
  }).catch(() => { devlog.querySelector(".dl-body").innerHTML = `<p class="dl-empty">Couldn't load the changelog. Try again later.</p>`; });
}
if(devlog && updates){                                        // skip if a cached older index.html lacks these elements
  changelogData.then(list => {                                // unreadable or empty: no sidebar block and no pop-up
    if(!list.length) return;
    document.getElementById("updatesList").innerHTML = list.slice(0, UPDATES_SHOWN).map(e => {
      const {day, hm, tz} = etTime(e.t);
      return `<li><button type="button" aria-haspopup="dialog"><time>${fmtDate(day,false)} ${hm}<small>${tz}</small></time><span>${esc(e.msg)}</span></button></li>`;
    }).join("");
    updates.hidden = false;
    if(!mapView.hidden && lb.hidden && !devlog.open) openDevlog();   // pops up on the home page, unless another page was opened before it loaded
  }).catch(()=>{});
  updates.addEventListener("click", e => { if(e.target.closest("button")) openDevlog(); });
  devlog.addEventListener("click", e => { if(e.target===devlog || e.target.closest(".dl-x")) devlog.close(); });   // the dialog has no padding, so a click on the element itself is a click outside
}

route();
